```typescript
// src/modules/products/templates/index.tsx
import { StructuredData } from "@components/seo/structured-data"

const ProductTemplate: React.FC<ProductTemplateProps> = async ({
  product,
  region,
  shippingOptions,
  countryCode,
}) => {
  // Build breadcrumb category chain
  let breadcrumbChain: any[] = []
  const cats = await listCategories({ limit: 200 })
  const allCats = cats || []
  const productCategories = allCats.filter((c: any) =>
    (c.products || []).some((p: any) => p.id === product.id)
  )

  if (productCategories.length > 0) {
    let leafCategory = null
    for (const cat of productCategories) {
      const hasChildWithProduct = productCategories.some(
        (otherCat: any) => otherCat.parent_category?.id === cat.id
      )
      if (!hasChildWithProduct) {
        leafCategory = cat
        break
      }
    }

    if (leafCategory) {
      const chain: any[] = [leafCategory]
      let cursor: any = leafCategory
      while (cursor?.parent_category) {
        chain.push(cursor.parent_category)
        cursor = cursor.parent_category
      }
      breadcrumbChain = chain.reverse()
    }
  }

  return (
    <>
      {/* Product Schema - Rich snippets for Google */}
      <StructuredData type="product" data={{ product, region, shippingOptions }} />
      
      {/* Breadcrumb Schema - Navigation structure */}
      <StructuredData 
