// src/lib/util/metadata-generator.ts
export function generateProductMetadata(config: ProductMetadataConfig): Metadata {
  const baseUrl = process.env.NEXT_PUBLIC_BASE_URL || "http://localhost:3000"
  const canonicalUrl = config.canonical ? `${baseUrl}${config.canonical}` : undefined

  const otherMetadata: Record<string, string> = {}
  if (config.price) otherMetadata["product:price:amount"] = config.price
  if (config.availability) otherMetadata["product:availability"] = config.availability
  if (config.brand) otherMetadata["product:brand"] = config.brand
  if (config.category) otherMetadata["product:category"] = config.category
  otherMetadata["product:price:currency"] = "GBP"

  return {
    title: config.title,
    description: config.description,
    keywords: config.keywords.join(", "),
    alternates: canonicalUrl ? { canonical: canonicalUrl } : undefined,
    robots: {
      index: !config.noIndex,
      follow: !config.noIndex,
      googleBot: {
        index: !config.noIndex,
        follow: !config.noIndex,
        "max-video-preview": -1,
        "max-image-preview": "large",
        "max-snippet": -1,
      },
    },
    openGraph: {
      title: config.title,
      description: config.description,
      url: canonicalUrl,
      images: config.images.length > 0 ? [{
        url: config.images[0],
        width: 1200,
        height: 630,
        alt: config.title,
      }] : undefined,
      type: "website",
      siteName: "Company Name",
      locale: "en_GB",
    },
    twitter: {
      card: "summary_large_image",
      title: config.title,
      description: config.description,
      images: config.images.length > 0 ? [config.images[0]] : undefined,
    },
    ...(Object.keys(otherMetadata).length > 0 && { other: otherMetadata }),
