import { NextResponse } from 'next/server';
import fs from 'fs';

export async function POST(request: Request) {
  const body = await request.json();
  fs.writeFileSync('.nyc_output/out.json', JSON.stringify(body));
  return NextResponse.json({ success: true });
}

📊 5️⃣ Generate Reports

After running your Cypress tests:

npx nyc report --reporter=html


Coverage reports will be created in the coverage/ folder.


🧠 Extra Notes

This pattern isolates Babel to the testing phase, avoiding performance overhead in dev/prod.

Turbopack still lacks official Babel plugin support, but this approach keeps your workflow consistent.

Reference: [@bahmutov/next-and-cypress-example](https://github.com/bahmutov/next-and-cypress-example)

