export function createMetadata({ url, img, ...options }: CreateMetadataOptions): Metadata {
  const title = options.title ?? siteShortDescription;
  const description = options.description ?? siteDescription;

  const titleString = typeof title === "string" ? title : siteShortDescription;
  const descriptionString = typeof description === "string" ? description : siteDescription;

