  return {
    title,
    description,
    openGraph: {
      title: titleString,
      description: descriptionString,
      siteName,
      locale: "en_US",
      type: "website",
      url: new URL(url, siteURL).toString(),
      images: [{ url: image, alt: siteShortDescription, height: 628, width: 1200 }],
      ...options.openGraph,
