      description: descriptionString,
      creator: "@ShyamVerma9240",
      card: "summary_large_image",
      images: [{ url: image }],
      ...options.twitter,
    },
    ...options,
  };
}

export function calculateMetadataFontSizes(titleLength: number, descLength: number) {
  return {
    titleFontSize: titleLength > 60 ? 48 : titleLength > 40 ? 56 : titleLength > 20 ? 64 : 72,
    descFontSize: descLength > 120 ? 24 : descLength > 80 ? 28 : 30,
  };
}

export function truncateMetadataDescription(description: string, maxLength = 160) {
  return description.length > maxLength
    ? `${description.substring(0, maxLength - 3)}...`
    : description;
}

export { siteName, siteURL, siteShortDescription, siteDescription };
